insert into portal_entries (id, data) values ('portal-arcade-update', $j${"id": "portal-arcade-update", "slug": "arcade-makeover", "title": "Eight Games, One Big Arcade Makeover", "description": "Every game on the Play page got a new arcade look. Watch a short preview of each one and see what changed.", "category": "New games", "layout": "article", "status": "draft", "publishedAt": "2026-10-30", "cover": {"src": "assets/newsletter/arcade-update/reel.gif", "alt": "A moving preview of eight games: Spelling Detective, Cosmic Blast!, Bounce and Bank, Air Hockey Arcade, Balloon Pop Math, Maze Quest, Fruit Drop and Memory Match"}, "coverStill": "assets/newsletter/arcade-update/reel-still.jpg", "body": "<p>This week every game on our Play page got a makeover: a brand-new arcade look, sound effects you can turn off with one button, and new ways to play. Below is a short moving preview of each game, what changed, and what kids learn while they play.</p><h2>Pathbuilder</h2><p><img src=\"assets/newsletter/arcade-update/pathbuilder.gif\" alt=\"Pathbuilder: a road crosses a green island from the house at one corner to the car&#x27;s driveway at the other, and the little red car drives along it, over the river on a bridge, home to the house\"></p><ul><li>The road now starts at your house, and the car waits across the island.</li><li>Build your road one card at a time: bridges cross rivers, tunnels go under rocks and ramps jump gaps.</li><li>When your road reaches the car, the car drives the whole road home to your house!</li><li>With 2 players you each build from your own house at the same time. The first road to reach its car wins.</li></ul><blockquote><p><strong>Engineering, planning and thinking in shapes.</strong> Kids plan a route before they build, turn each piece in their head to see if it fits, and fix their plan when a road does not work, just like real engineers.</p></blockquote><p><a href=\"#/play/game-pathbuilder\">Play Pathbuilder</a></p><h2>Spelling Detective</h2><p><img src=\"assets/newsletter/arcade-update/spelling-detective.gif\" alt=\"Spelling Detective: Chike gives a thumbs up beside a case card with the clue The green part of a tree, a wrong letter is crossed out and the word LEAF is solved\"></p><ul><li>A detective case with Chike. Read the clue on the case card and crack the hidden word.</li><li>Pick your grade, from Kindergarten to 5th. Each grade has its own words.</li><li>A wrong letter uses up one of your magnifying glasses, so think before you guess.</li><li>Stuck? Press Get a clue and Chike finds a letter for you, once per case.</li></ul><blockquote><p><strong>Spelling, phonics and reading for meaning.</strong> Kids sound out words, use a clue to think about what a word means, and learn to think before they guess.</p></blockquote><p><a href=\"#/play/game-spelling\">Play Spelling Detective</a></p><h2>Cosmic Blast!</h2><p><img src=\"assets/games/ufo-target-practice.jpg\" alt=\"Cosmic Blast!: a white spaceship flies toward Saturn, aiming at a group of flying saucers\"></p><ul><li>Fly past all eight planets, Mercury to Neptune. Each planet is a level with its own points goal.</li><li>From Earth on, some aliens shoot back. From Jupiter on, radar drones can jam your laser.</li><li>Reach the goal and a spinning black hole pulls you through to the next planet, with a fun fact about it.</li><li>Switch between three lasers. The planets you reach and your best scores are saved.</li></ul><blockquote><p><strong>Space science, focus and hand-eye coordination.</strong> Kids learn the order of the planets and a fun fact about each one, and the efficiency score rewards careful aiming over wild firing.</p></blockquote><p><a href=\"#/play/game-ufo\">Play Cosmic Blast!</a></p><h2>Bounce &amp; Bank</h2><p><img src=\"assets/newsletter/arcade-update/bounce-and-bank.gif\" alt=\"Bounce and Bank: glowing balls bounce down a neon peg board into money slots, and one lands in the $100 jackpot\"></p><ul><li>A neon arcade cabinet, with a cash receipt that prints every ball&#x27;s win.</li><li>Drop balls through glowing pegs into the slots, from the $100 jackpot to a few that cost you $10.</li><li>Spend bank money on extra balls, including 2x and 3x balls that multiply their slot.</li><li>Grow your bank to $1,000 over six games. Your all-time high score is saved.</li></ul><blockquote><p><strong>Money math, saving and smart choices.</strong> Kids add up their winnings, save toward a goal, and decide whether an extra ball is worth what it costs.</p></blockquote><p><a href=\"#/play/game-bounce-and-bank\">Play Bounce &amp; Bank</a></p><h2>Air Hockey Arcade</h2><p><img src=\"assets/newsletter/arcade-update/air-hockey.gif\" alt=\"Air Hockey Arcade: a glowing 3D air hockey table in a neon arcade room, where a puck goes into Chike&#x27;s goal and the scoreboard flashes GOAL! plus 6\"></p><ul><li>Rebuilt as a full-screen 3D table. You stand at your end and Chike guards the far goal.</li><li>Five numbered pucks are in play at once. Knock one into Chike&#x27;s goal to score its number.</li><li>The LED scoreboard adds up the goals as you go. First to 25 wins.</li><li>At the end you see the whole match: every puck each side scored, added up to the final score.</li></ul><blockquote><p><strong>Mental math, quick reactions and good sportsmanship.</strong> Every goal adds a number to the score, so kids add as they play, and learn to win and lose gracefully.</p></blockquote><p><a href=\"#/play/game-air-hockey\">Play Air Hockey Arcade</a></p><h2>Balloon Pop Math</h2><p><img src=\"assets/newsletter/arcade-update/balloon-pop-math.gif\" alt=\"Balloon Pop Math: striped hot-air balloons with numbers float in a blue sky under the question 25 plus 27, the balloon with 52 pops and Chike says Nice\"></p><ul><li>Rebuilt with grades from Kindergarten to 5th. Each grade has its own kind of math.</li><li>Pop the balloon with the right answer, or type it. Rounds are 25 questions, with up to three stars.</li><li>After two misses Chike gives a hint, and Show me how opens his chalkboard to work it out step by step.</li><li>Your place is saved, so you can stop and come back later.</li></ul><blockquote><p><strong>Math at every grade, and learning from mistakes.</strong> From counting in Kindergarten to multiplying and dividing in 5th grade, with hints and step-by-step help that show how to get the answer, not just what it is.</p></blockquote><p><a href=\"#/play/game-balloon-math\">Play Balloon Pop Math</a></p><h2>Maze Quest</h2><p><img src=\"assets/newsletter/arcade-update/maze-quest.gif\" alt=\"Maze Quest: an explorer walks through a hedge maze in Sunny Woods, then the Old Wizard appears with a math question and four answers\"></p><ul><li>Now a walk through eight forests, from the camp tent to the cabin.</li><li>Pick your explorer from 8 characters, and pick your grade from Kindergarten to 5th.</li><li>Glowing lanterns call the Old Wizard, who asks a question for your grade. Answer right and you jump ten squares ahead.</li><li>New: race a friend online. Make a room, share the 6-character code, and the first to reach the cabin wins each forest.</li></ul><blockquote><p><strong>Problem solving, math and spelling, and friendly competition.</strong> Kids find their way through each maze, answer questions at their own grade, and race a friend fairly.</p></blockquote><p><a href=\"#/play/game-maze\">Play Maze Quest</a></p><h2>Fruit Drop</h2><p><img src=\"assets/newsletter/arcade-update/fruit-drop.gif\" alt=\"Fruit Drop: fruit falls into a glowing well at a fruit-stand arcade, a chain of matches pops and the words Sweet! Chain x2 and Row clear! flash while Chike cheers\"></p><ul><li>DropBlox is now Fruit Drop, a brand-new game that mixes falling pieces with match-three.</li><li>Line up 3 or more of the same fruit to pop them. A full row clears too, and falling fruit can set off chains.</li><li>Make striped, wrapped and golden-star fruit for big pops.</li><li>12 levels with up to three stars each, plus an Endless mode. On a phone, use the big buttons or swipe.</li></ul><blockquote><p><strong>Patterns, planning ahead and strategy.</strong> Kids spot patterns, think a few moves ahead, and set up chain reactions on purpose.</p></blockquote><p><a href=\"#/play/game-drop-blox\">Play Fruit Drop</a></p><h2>Memory Match</h2><p><img src=\"assets/newsletter/arcade-update/memory-match.gif\" alt=\"Memory Match: yellow cards flip over to show drawn pictures, and matching pairs like two books and two crayons get a green tick\"></p><ul><li>New hand-drawn cards: books, crayons, puzzles, rockets, palettes and more.</li><li>Find all ten pairs. A matching pair stays face up with a green tick.</li><li>Your best time is saved, so you can try to beat it.</li></ul><blockquote><p><strong>Memory, focus and concentration.</strong> Kids remember where each picture was and find its pair, building their memory one flip at a time.</p></blockquote><p><a href=\"#/play/game-memory\">Play Memory Match</a></p><h2>Also new</h2><ul><li><strong>Chike's Gravity 4</strong>, our subscribers-only game: Easy Chike is now easier to beat, and the game has sound.</li><li><strong>The Play page:</strong> smaller game cards, so you can see more games at once.</li></ul><p>And <strong>Doodle Dash</strong> is still our most popular game. Have you drawn your own level yet?</p><p><a href=\"#/play/game-doodle-dash\">Play Doodle Dash</a></p>", "textFirst": "after", "email": {"on": true, "subject": "8 games just got an arcade makeover", "preview": "Fruit Drop, a Maze Quest race, 3D Air Hockey and more. Come see what's new.", "message": "Dear parents and educators,\n\nBig news from our Online Games page: eight games just got a brand-new arcade makeover, and every one now has a learning twist for kids from Kindergarten to 5th grade.\n\nIn **Pathbuilder**, kids now build a road from their house all the way to their car. When the road reaches it, the car drives the whole road home, a fun lesson in planning and engineering.\n\n**Air Hockey** is now a 3D table against Chike, with numbered pucks that keep kids adding as they play. **Cosmic Blast!** flies past all eight planets, with a fun fact about each one. **Maze Quest** lets kids race a friend online with a room code, and they can pick their own grade level, from Kindergarten to 5th. And **DropBlox** became **Fruit Drop**: match three fruit and set off juicy chains while spotting patterns.\n\n**Spelling Detective** and **Balloon Pop Math** now let kids pick their grade, with Chike there to give hints, and **Bounce & Bank** and **Memory Match** have a fresh new look.\n\nIn the Subscriber's Portal you'll find a short moving preview of every game, what changed, and what kids learn while they play.\n\nAnd **Doodle Dash** is still our most popular game. Ask your young creator to draw their own level!", "button": "See the new games"}, "adminNote": "Draft written by Claude on 2026-10-30. NOT sent. Publishing this entry opens its email as a draft for you to review; nothing is emailed until you press Send yourself.", "gameId": "", "gamePath": "", "gameMode": "launch", "gameLabel": "", "howToPlay": [], "privateGameId": "", "privateGameKb": 0, "bookId": "", "bookMode": "launch", "bookPath": "", "videoUrl": "", "gallery": [], "buttonLabel": "", "buttonUrl": "", "vocabWord": "", "vocabSay": "", "vocabMeaning": "", "vocabExample": "", "aiPrompt": "", "aiPromptTitle": "", "aiPromptTip": "", "emailId": "news-arcade-update", "createdAt": "2026-10-30T12:00:00.000Z", "updatedAt": "2026-10-30T12:00:00.000Z"}$j$::jsonb)
